#include <string>
#include <algorithm>

class Solution {
public:
    long long sumOfPrimes(int n) {
        std::string s = std::to_string(n);
        std::reverse(s.begin(), s.end());
        int r = std::stoi(s);
        int low = std::min(n, r);
        int high = std::max(n, r);

        auto isPrime = [](int x) -> bool {
            if (x < 2) return false;
            if (x == 2 || x == 3) return true;
            if (x % 2 == 0 || x % 3 == 0) return false;
            for (int i = 5; (long long)i * i <= x; i += 6) {
                if (x % i == 0 || x % (i + 2) == 0) return false;
            }
            return true;
        };

        long long ans = 0;
        for (int i = low; i <= high; ++i) {
            if (isPrime(i)) ans += i;
        }
        return ans;
    }
};

class Solution {
    public long sumOfPrimes(int n) {
        String s = new StringBuilder(Integer.toString(n)).reverse().toString();
        int r = Integer.parseInt(s);
        int low = Math.min(n, r);
        int high = Math.max(n, r);
        long ans = 0;
        for (int i = low; i <= high; i++) {
            if (isPrime(i)) ans += i;
        }
        return ans;
    }

    private boolean isPrime(int x) {
        if (x < 2) return false;
        if (x == 2 || x == 3) return true;
        if (x % 2 == 0 || x % 3 == 0) return false;
        for (int i = 5; (long)i * i <= x; i += 6) {
            if (x % i == 0 || x % (i + 2) == 0) return false;
        }
        return true;
    }
}

